<?php
namespace Nakhostin\PerformanceEngine\Optimization;
final class OptimizationPolicy { public function allows( OptimizationContext $context, ?OptimizationManifest $manifest, string $feature, bool $enabled ): array { if ( ! $enabled ) { return array( 'allowed' => false, 'reason' => 'feature-disabled' ); } if ( $context->is_protected() ) { return array( 'allowed' => false, 'reason' => 'protected-context' ); } if ( ! $manifest ) { return array( 'allowed' => false, 'reason' => 'manifest-missing' ); } if ( $manifest->is_stale() ) { return array( 'allowed' => false, 'reason' => 'manifest-stale' ); } $providers = (array) $context->get( 'providers', array() ); if ( 'npe' !== ( $providers[ $feature ] ?? 'none' ) ) { return array( 'allowed' => false, 'reason' => 'provider-conflict' ); } return array( 'allowed' => true, 'reason' => 'approved-manifest' ); } }
